  ('1fcddc84-3230-5ebb-a774-61b3858d83d3', 'BM-1352525', 'HV-1001 1/8', 'Skripka Vivaldi 1/8 HV-1001', 'Скрипка Vivaldi 1/8 HV-1001', 'Skripka Vivaldi 1/8 HV-1001', 200, NULL, 'Vivaldi', 'yayli-aletler', 'yayli-smicoklar', 'https://strgimgr.umico.az/img/product/1680/d58d8566-86aa-4a03-8ea8-b10d41b7b445.jpeg', '["https://strgimgr.umico.az/img/product/1680/d58d8566-86aa-4a03-8ea8-b10d41b7b445.jpeg","https://strgimgr.umico.az/img/product/1680/692ceade-23f9-43fc-9b60-1d77c4488f62.jpeg","https://strgimgr.umico.az/img/product/1680/af0e066c-128e-44b1-af48-780130316646.jpeg","https://strgimgr.umico.az/img/product/1680/5a434d86-b2e9-496e-8543-4ddd075fa7b8.jpeg","https://strgimgr.umico.az/img/product/1680/1e35d65b-8f49-4f77-95a1-2af3963ed13e.jpeg","https://strgimgr.umico.az/img/product/1680/b3565f14-60a6-4880-8e87-21928351bc70.jpeg"]'::jsonb, 'Model: HV-1001 (tam ölçü 1/8 həmçinin uşaqlar üçün digər ölçülərdə də olur)

